#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Shared CLI utilities for has_text commands.

Contains argument validation, I/O helpers, error handling, and output
formatting used by all three subcommands (hide, restore, scan).
"""

from __future__ import annotations

import argparse
from dataclasses import dataclass
import json
import os
from pathlib import Path
import sys
import time
from typing import Any, Dict, List, Optional, Tuple

from .mapping import has_tags, load_mapping, save_mapping
from .parallel import DEFAULT_MAX_PARALLEL_REQUESTS, resolve_parallel_workers


# Rough token estimate used only for pre-server slot planning.
# Actual chunking always uses the real tokenizer via HaSClient.count_tokens.
def estimate_tokens_for_planning(text: str) -> int:
    """Conservative character-based estimate, used only before the server starts."""
    if not text:
        return 0
    # ~0.5 tokens per character is conservative for mixed CJK/Latin text.
    return max(1, int(len(text) * 0.5))


# Fallback context size when the default 8K is too small (mapping overflow).
FALLBACK_CONTEXT_PER_SLOT = 16384

SCHEMA_VERSION = "1"


@dataclass(frozen=True)
class CLIError(Exception):
    code: str
    message: str

    def __str__(self) -> str:
        return self.message


class StructuredArgumentParser(argparse.ArgumentParser):
    """ArgumentParser that reports machine-readable errors."""

    def error(self, message: str) -> None:
        raise CLIError("invalid_arguments", message)


def emit_json(payload: dict[str, Any], *, stream=None) -> None:
    target = stream or sys.stdout
    print(json.dumps(payload, ensure_ascii=False, separators=(",", ":")), file=target)


def error_payload(code: str, message: str) -> dict[str, Any]:
    return {
        "schema_version": SCHEMA_VERSION,
        "error": {
            "code": code,
            "message": message,
        },
    }


def fatal(code: str, message: str) -> None:
    raise CLIError(code, message)


def absolute_path(path: Path | str) -> str:
    """Return a stable absolute path string without resolving symlink targets."""
    return str(Path(path).expanduser().absolute())


def read_text(args: argparse.Namespace) -> str:
    """Read input text from --text, --file, or stdin."""
    if hasattr(args, "text") and args.text:
        return args.text
    if hasattr(args, "file") and args.file:
        with open(args.file, "r", encoding="utf-8") as f:
            return f.read()
    # Try stdin
    if not sys.stdin.isatty():
        return sys.stdin.read()
    fatal("missing_input", "Provide exactly one input source via --text, --file, --dir, or stdin.")


def parse_types(type_values: Optional[List[str]]) -> List[str]:
    """Parse repeated --type flags into a normalized list."""
    if not type_values:
        fatal("missing_type", "Provide at least one --type value.")

    parsed: List[str] = []
    for raw_value in type_values:
        value = str(raw_value).strip()
        if not value:
            fatal("invalid_type", "--type values must be non-empty strings.")
        if value not in parsed:
            parsed.append(value)
    return parsed


def load_mapping_file(path: str) -> Dict[str, List[str]]:
    mapping_path = Path(path)
    if not mapping_path.is_file():
        fatal("mapping_not_found", f"Mapping file not found: {path}")
    return load_mapping(str(mapping_path))


def output(
    command: str,
    result: dict[str, Any],
    *,
    timing: bool = False,
    elapsed_ms: Optional[int] = None,
) -> None:
    payload: dict[str, Any] = {
        "schema_version": SCHEMA_VERSION,
        "command": command,
    }
    payload.update(result)
    if timing and elapsed_ms is not None:
        payload["elapsed_ms"] = elapsed_ms
    emit_json(payload)


def parallel_default() -> int:
    """Read the shared parallel request budget from the environment."""
    raw = os.environ.get("HAS_TEXT_MAX_PARALLEL_REQUESTS")
    if raw is None:
        return DEFAULT_MAX_PARALLEL_REQUESTS

    try:
        value = int(raw)
    except ValueError:
        fatal("invalid_env", "HAS_TEXT_MAX_PARALLEL_REQUESTS must be an integer >= 1")

    if value < 1:
        fatal("invalid_env", "HAS_TEXT_MAX_PARALLEL_REQUESTS must be >= 1")

    return value


def required_slots(total_requests: int, max_parallel_requests: int) -> int:
    """Clamp server slots to the actual model work for this command."""
    if total_requests <= 0:
        return 0
    return resolve_parallel_workers(total_requests, max_parallel_requests)


def read_utf8_text_file(path: Path) -> Tuple[Optional[str], Optional[str]]:
    """Read a plaintext file, rejecting binary and non-UTF-8 content."""
    try:
        with path.open("rb") as fh:
            sample = fh.read(8192)
    except OSError as exc:
        return None, str(exc)

    if b"\x00" in sample:
        return None, "binary"

    try:
        return path.read_text(encoding="utf-8"), None
    except UnicodeDecodeError:
        return None, "non_utf8"
    except OSError as exc:
        return None, str(exc)


def is_within_directory(path: Path, directory: Path) -> bool:
    """Return whether `path` resolves within `directory`."""
    try:
        path.relative_to(directory)
        return True
    except ValueError:
        return False


def collect_text_documents(dir_path: str) -> Tuple[List[Dict[str, str]], List[Dict[str, str]]]:
    """Collect immediate plaintext files from a directory."""
    directory = Path(dir_path)
    if not directory.is_dir():
        fatal("invalid_directory", f"Not a directory: {dir_path}")
    directory_root = directory.resolve()

    documents: List[Dict[str, str]] = []
    skipped: List[Dict[str, str]] = []

    for entry in sorted(directory.iterdir()):
        if not entry.is_file():
            continue
        try:
            resolved_entry = entry.resolve()
        except OSError as exc:
            skipped.append({"file": absolute_path(entry), "reason": str(exc)})
            continue
        if not is_within_directory(resolved_entry, directory_root):
            skipped.append({"file": absolute_path(entry), "reason": "symlink_escape"})
            continue
        text, skip_reason = read_utf8_text_file(entry)
        if text is None:
            skipped.append({"file": absolute_path(entry), "reason": skip_reason or "unreadable"})
            continue
        documents.append({"file": absolute_path(entry), "text": text})

    return documents, skipped


def write_text_output(path: Path, text: str) -> None:
    """Write UTF-8 text with restrictive permissions (0600).

    Both anonymized and restored text may contain sensitive information.
    Match the restrictive permissions used by save_mapping.
    """
    import os as _os

    path.parent.mkdir(parents=True, exist_ok=True)
    fd = _os.open(str(path), _os.O_WRONLY | _os.O_CREAT | _os.O_TRUNC, 0o600)
    try:
        if hasattr(_os, "fchmod"):
            _os.fchmod(fd, 0o600)
        else:
            _os.chmod(str(path), 0o600)
        f = _os.fdopen(fd, "w", encoding="utf-8")
    except Exception:
        _os.close(fd)
        raise
    with f:
        f.write(text)


def resolve_single_output_path(
    path_value: Optional[str],
    *,
    input_path: Optional[Path] = None,
    input_label: str = "input file",
) -> Optional[Path]:
    """Resolve a single-file output path and refuse obvious clobbers."""
    if not path_value:
        return None

    output_path = Path(path_value)
    if input_path is not None and output_path.resolve(strict=False) == input_path.resolve(strict=False):
        fatal("refusing_overwrite", f"Refusing to overwrite {input_label}: {input_path}")
    return output_path


def default_seek_mapping_dir(dir_path: str) -> Path:
    """Return the default per-file mapping directory for batch restore."""
    return Path(dir_path) / "mappings"


def default_restore_output_dir(dir_path: str) -> Path:
    """Return the default output directory for batch restore.

    If the input directory sits directly under a `.has/` parent
    (e.g. `docs/.has/anonymized/`), place `restored/` as a sibling
    under the same `.has/` tree → `docs/.has/restored/`.
    Otherwise fall back to `<input-dir>/.has/restored/`.
    """
    d = Path(dir_path)
    if d.parent.name == ".has":
        return d.parent / "restored"
    return d / ".has" / "restored"


def seek_mapping_path(mapping_dir: Path, source_path: Path) -> Path:
    """Return the per-file mapping path generated by `hide --dir`."""
    return mapping_dir / f"{source_path.name}.mapping.json"

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""scan command — Identify sensitive entities in text (NER only, no anonymization)."""

from __future__ import annotations

import argparse
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass
from typing import Any, Callable, Dict, List, Optional

from ..chunker import chunk_text
from ..client import HaSClient
from ..mapping import parse_json_tolerant
from ..parallel import DEFAULT_MAX_PARALLEL_REQUESTS, resolve_parallel_workers
from ..prompts import build_ner_messages
from ..validation import normalize_entity_map

# scan only produces a small JSON entity list (no full-text rewrite),
# so chunks can be larger than the 3000 default used by hide/seek.
DEFAULT_SCAN_MAX_CHUNK_TOKENS = 5000


@dataclass(frozen=True)
class ScanDocument:
    """Plaintext input for batch scanning."""

    source: str
    text: str


@dataclass(frozen=True)
class _ScanTask:
    document_index: int
    chunk_index: int
    text: str


def _scan_single_chunk(
    client: HaSClient,
    chunk_text_str: str,
    types: List[str],
    chunk_index: int,
) -> Dict[str, List[str]]:
    """Run NER for a single chunk."""
    messages = build_ner_messages(chunk_text_str, types)
    raw_output = client.chat(messages)
    return normalize_entity_map(
        parse_json_tolerant(raw_output),
        context=f"NER output for chunk {chunk_index + 1}",
    )


def _clone_scan_client(client: HaSClient) -> HaSClient:
    """Create a fresh client per worker to avoid sharing HTTP sessions."""
    client_cls = client.__class__
    try:
        return client_cls(client.base_url)
    except TypeError:
        return HaSClient(client.base_url)


def _merge_entities(chunk_results: List[Dict[str, List[str]]]) -> Dict[str, List[str]]:
    """Merge chunk results while preserving the first-seen order."""
    merged_entities: Dict[str, List[str]] = {}

    for ner_result in chunk_results:
        for entity_type, entities in ner_result.items():
            if entity_type not in merged_entities:
                merged_entities[entity_type] = []
            for entity in entities:
                entity_str = str(entity).strip()
                if entity_str and entity_str not in merged_entities[entity_type]:
                    merged_entities[entity_type].append(entity_str)

    return merged_entities


def estimate_scan_request_count(
    text: str,
    max_chunk_tokens: int = DEFAULT_SCAN_MAX_CHUNK_TOKENS,
    *,
    count_tokens: Callable[[str], int],
) -> int:
    """Estimate how many model requests scan will issue for one text."""
    if not text or not text.strip():
        return 0
    return len(chunk_text(text, count_tokens, max_chunk_tokens))


def estimate_scan_batch_request_count(
    documents: List[ScanDocument],
    max_chunk_tokens: int = DEFAULT_SCAN_MAX_CHUNK_TOKENS,
    *,
    count_tokens: Callable[[str], int],
) -> int:
    """Estimate total scan requests across a batch of documents."""
    return sum(
        estimate_scan_request_count(
            document.text,
            max_chunk_tokens=max_chunk_tokens,
            count_tokens=count_tokens,
        )
        for document in documents
    )


def run_scan(
    client: HaSClient,
    text: str,
    types: List[str],
    max_chunk_tokens: int = DEFAULT_SCAN_MAX_CHUNK_TOKENS,
    max_parallel_requests: int = DEFAULT_MAX_PARALLEL_REQUESTS,
) -> Dict[str, List[str]]:
    """Scan text for sensitive entities.

    For short text, runs a single NER call.
    For long text, chunks and merges NER results.

    Returns:
        {"entities": {"人名": ["张三", "李四"], "地址": ["北京"], ...}}
    """
    if max_parallel_requests < 1:
        raise ValueError("max_parallel_requests must be >= 1")

    chunks = chunk_text(text, client.count_tokens, max_chunk_tokens)
    if not chunks:
        return {"entities": {}}

    if len(chunks) == 1 or max_parallel_requests == 1:
        chunk_results = [
            _scan_single_chunk(client, chunk.text, types, chunk.index)
            for chunk in chunks
        ]
        return {"entities": _merge_entities(chunk_results)}

    max_workers = resolve_parallel_workers(len(chunks), max_parallel_requests)
    chunk_results: List[Optional[Dict[str, List[str]]]] = [None] * len(chunks)

    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {
            executor.submit(
                _scan_single_chunk,
                _clone_scan_client(client),
                chunk.text,
                types,
                chunk.index,
            ): chunk.index
            for chunk in chunks
        }

        try:
            for future in as_completed(futures):
                chunk_index = futures[future]
                chunk_results[chunk_index] = future.result()
        except BaseException:
            for future in futures:
                future.cancel()
            raise

    # Merge in original chunk order so first-seen semantics remain stable.
    return {"entities": _merge_entities([result for result in chunk_results if result is not None])}


def run_scan_batch(
    client: HaSClient,
    documents: List[ScanDocument],
    types: List[str],
    max_chunk_tokens: int = DEFAULT_SCAN_MAX_CHUNK_TOKENS,
    max_parallel_requests: int = DEFAULT_MAX_PARALLEL_REQUESTS,
) -> Dict[str, Any]:
    """Scan multiple plaintext documents with a shared global request pool."""
    if max_parallel_requests < 1:
        raise ValueError("max_parallel_requests must be >= 1")

    if not documents:
        return {"results": [], "count": 0, "summary": {}}

    chunk_results: List[List[Optional[Dict[str, List[str]]]]] = []
    tasks: List[_ScanTask] = []

    for document_index, document in enumerate(documents):
        chunks = chunk_text(document.text, client.count_tokens, max_chunk_tokens)
        doc_results: List[Optional[Dict[str, List[str]]]] = [None] * len(chunks)
        chunk_results.append(doc_results)
        for chunk in chunks:
            tasks.append(
                _ScanTask(
                    document_index=document_index,
                    chunk_index=chunk.index,
                    text=chunk.text,
                )
            )

    if len(tasks) == 1 or max_parallel_requests == 1:
        for task in tasks:
            chunk_results[task.document_index][task.chunk_index] = _scan_single_chunk(
                client,
                task.text,
                types,
                task.chunk_index,
            )
    elif tasks:
        max_workers = resolve_parallel_workers(len(tasks), max_parallel_requests)
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            futures = {
                executor.submit(
                    _scan_single_chunk,
                    _clone_scan_client(client),
                    task.text,
                    types,
                    task.chunk_index,
                ): task
                for task in tasks
            }

            try:
                for future in as_completed(futures):
                    task = futures[future]
                    chunk_results[task.document_index][task.chunk_index] = future.result()
            except BaseException:
                for future in futures:
                    future.cancel()
                raise

    results: List[Dict[str, Any]] = []
    summary: Dict[str, int] = {}

    for document_index, document in enumerate(documents):
        entities = _merge_entities(
            [result for result in chunk_results[document_index] if result is not None]
        )
        results.append({"file": document.source, "entities": entities})
        for entity_type, values in entities.items():
            summary[entity_type] = summary.get(entity_type, 0) + len(values)

    return {
        "results": results,
        "count": len(results),
        "summary": summary,
    }


# ======================================================================
# CLI handler
# ======================================================================


def cmd_scan(args: argparse.Namespace) -> None:
    """Execute the scan (NER) command."""
    from ..cli_utils import (
        collect_text_documents,
        estimate_tokens_for_planning,
        output,
        parse_types,
        read_text,
        required_slots,
    )
    from ..client import DEFAULT_SERVER
    from ..server_runtime import acquire_server

    types = parse_types(args.type)
    dir_path = getattr(args, "dir", None)

    t0 = time.time()
    if dir_path:
        raw_documents, skipped = collect_text_documents(dir_path)
        documents = [
            ScanDocument(source=item["file"], text=item["text"])
            for item in raw_documents
        ]
        request_count = estimate_scan_batch_request_count(
            documents,
            max_chunk_tokens=args.max_chunk_tokens,
            count_tokens=estimate_tokens_for_planning,
        )

        if documents and request_count > 0:
            with acquire_server(
                DEFAULT_SERVER,
                required_slots=required_slots(request_count, args.max_parallel_requests),
            ) as lease:
                client = lease.create_client()
                result = run_scan_batch(
                    client,
                    documents,
                    types,
                    max_chunk_tokens=args.max_chunk_tokens,
                    max_parallel_requests=args.max_parallel_requests,
                )
        elif documents:
            result = {
                "results": [
                    {"file": document.source, "entities": {}}
                    for document in documents
                ],
                "count": len(documents),
                "summary": {},
            }
        else:
            result = {"results": [], "count": 0, "summary": {}}

        if skipped:
            result["skipped"] = skipped
            result["skipped_count"] = len(skipped)
    else:
        text = read_text(args)
        request_count = estimate_scan_request_count(
            text,
            max_chunk_tokens=args.max_chunk_tokens,
            count_tokens=estimate_tokens_for_planning,
        )
        if request_count > 0:
            with acquire_server(
                DEFAULT_SERVER,
                required_slots=required_slots(request_count, args.max_parallel_requests),
            ) as lease:
                client = lease.create_client()
                result = run_scan(
                    client,
                    text,
                    types,
                    max_chunk_tokens=args.max_chunk_tokens,
                    max_parallel_requests=args.max_parallel_requests,
                )
        else:
            result = {"entities": {}}
    elapsed_ms = round((time.time() - t0) * 1000)

    output("scan", result, timing=args.timing, elapsed_ms=elapsed_ms)

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""seek command — Restore anonymized text (Phase 3 of HaS workflow).

Internal workflow:
    Check for tags → Language detection → Tool-Seek or Model-Seek
    → Self-check → Model-Seek fallback
"""

from __future__ import annotations

import argparse
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass
import os
from pathlib import Path
import sys
import time
from typing import Any, Callable, Dict, List, Optional, Tuple

from ..chunker import (
    DEFAULT_MAX_CHUNK_TOKENS,
    _FALLBACK_BOUNDARIES,
    _SENTENCE_BOUNDARIES,
)
from ..client import HaSClient
from ..lang import is_same_language
from ..mapping import (
    TAG_PATTERN,
    find_composite_entries,
    has_tags,
    normalize_mapping_dict,
    parse_json_tolerant,
)
from ..parallel import DEFAULT_MAX_PARALLEL_REQUESTS, resolve_parallel_workers
from ..prompts import build_seek_messages, build_split_messages




@dataclass(frozen=True)
class _KeyOccurrence:
    key: str
    start: int
    end: int


@dataclass(frozen=True)
class _SeekChunk:
    text: str
    index: int
    start_char: int
    end_char: int
    mapping: Dict[str, List[str]]
    needs_model: bool
    prompt_token_count: int


@dataclass(frozen=True)
class SeekDocument:
    """Plaintext input for batch restoration."""

    source: str
    text: str


def _warn(message: str) -> None:
    if os.environ.get("HAS_TEXT_VERBOSE") == "1":
        print(f"Warning: {message}", file=sys.stderr)


def _clone_seek_client(client: HaSClient) -> HaSClient:
    """Create a fresh client per worker to avoid sharing HTTP sessions."""
    client_cls = client.__class__
    try:
        return client_cls(client.base_url)
    except TypeError:
        return HaSClient(client.base_url)


# ======================================================================
# Tool-Seek: deterministic string replacement
# ======================================================================


def _tool_seek(text: str, mapping: Dict[str, List[str]]) -> str:
    """Restore text by replacing tags with original values.

    Uses the first value in each tag's value array.
    """
    restored = text
    # Replace longer composite tags first so unresolved composite mappings can
    # still restore correctly.
    for tag, values in sorted(mapping.items(), key=lambda item: len(item[0]), reverse=True):
        if values:
            restored = restored.replace(tag, str(values[0]))
    return restored


# ======================================================================
# Seek self-check
# ======================================================================


def _seek_self_check(restored_text: str) -> bool:
    """Check if the restored text still contains unreplaced tags.

    Returns True if no tags remain (success).
    """
    return not has_tags(restored_text)


def _should_try_tool_seek(
    text: str,
    mapping: Dict[str, List[str]],
    original_text: Optional[str] = None,
) -> bool:
    """Return whether deterministic seek is likely sufficient."""
    if original_text:
        return is_same_language(original_text, text)

    entity_sample = " ".join(val for vals in mapping.values() for val in vals[:2])
    if not entity_sample.strip():
        return True
    return is_same_language(entity_sample, text)


def restore_without_model(
    text: str,
    mapping: Dict[str, List[str]],
    original_text: Optional[str] = None,
) -> Optional[str]:
    """Restore text without llama-server when deterministic replacement succeeds."""
    if not has_tags(text):
        return text

    if not _should_try_tool_seek(text, mapping, original_text=original_text):
        return None

    restored = _tool_seek(text, mapping)
    if _seek_self_check(restored):
        return restored
    return None


def _normalize_seek_mapping(
    client: HaSClient,
    text: str,
    mapping: Dict[str, List[str]],
) -> Dict[str, List[str]]:
    """Split composite mappings that no longer appear literally in the text."""
    atomic, composite = find_composite_entries(mapping)
    if not composite:
        return mapping

    preserved = {key: values for key, values in composite.items() if key in text}
    unresolved = {key: values for key, values in composite.items() if key not in text}
    if not unresolved:
        return mapping

    messages = build_split_messages([{key: values} for key, values in unresolved.items()])
    raw_output = client.chat(messages)
    split_result = parse_json_tolerant(raw_output)

    try:
        if isinstance(split_result, dict):
            normalized_split = normalize_mapping_dict(split_result)
        elif isinstance(split_result, list):
            merged: Dict[str, Any] = {}
            for item in split_result:
                if not isinstance(item, dict):
                    raise ValueError("Model-Split returned a non-object entry")
                merged.update(item)
            normalized_split = normalize_mapping_dict(merged)
        else:
            raise ValueError("Model-Split did not return valid JSON")
    except ValueError as exc:
        _warn(
            "Model-Split failed while preparing seek mapping; "
            f"falling back to original composite mappings ({exc})"
        )
        return mapping

    merged_mapping: Dict[str, List[str]] = {}
    merged_mapping.update(atomic)
    merged_mapping.update(normalized_split)
    merged_mapping.update(preserved)

    for key, values in unresolved.items():
        if key not in merged_mapping:
            merged_mapping[key] = values

    return merged_mapping


def _find_key_occurrences(text: str, mapping: Dict[str, List[str]]) -> List[_KeyOccurrence]:
    occurrences: List[_KeyOccurrence] = []
    for key in mapping:
        start = 0
        while True:
            index = text.find(key, start)
            if index < 0:
                break
            occurrences.append(_KeyOccurrence(key=key, start=index, end=index + len(key)))
            start = index + 1
    occurrences.sort(key=lambda item: (item.start, -(item.end - item.start), item.key))
    return occurrences


def _has_uncovered_tags(text: str, occurrences: List[_KeyOccurrence]) -> bool:
    for match in TAG_PATTERN.finditer(text):
        tag_start = match.start()
        tag_end = match.end()
        if not any(item.start <= tag_start and item.end >= tag_end for item in occurrences):
            return True
    return False


def _is_safe_split(pos: int, occurrences: List[_KeyOccurrence]) -> bool:
    return all(not (item.start < pos < item.end) for item in occurrences)


def _local_mapping_for_prefix(
    mapping: Dict[str, List[str]],
    occurrences: List[_KeyOccurrence],
    end_pos: int,
) -> Dict[str, List[str]]:
    included = {item.key for item in occurrences if item.end <= end_pos}
    return {key: values for key, values in mapping.items() if key in included}


def _count_seek_prompt_tokens(
    count_tokens,
    text: str,
    mapping: Dict[str, List[str]],
) -> int:
    if not has_tags(text):
        return 0
    messages = build_seek_messages(mapping, text)
    return count_tokens(messages[0]["content"])


def _plan_seek_chunks_from_mapping(
    text: str,
    mapping: Dict[str, List[str]],
    count_tokens: Callable[[str], int],
    max_chunk_tokens: int,
) -> List[_SeekChunk]:
    occurrences = _find_key_occurrences(text, mapping)

    if _has_uncovered_tags(text, occurrences):
        prompt_tokens = _count_seek_prompt_tokens(count_tokens, text, mapping)
        if prompt_tokens <= max_chunk_tokens:
            return [
                _SeekChunk(
                    text=text,
                    index=0,
                    start_char=0,
                    end_char=len(text),
                    mapping=mapping,
                    needs_model=True,
                    prompt_token_count=prompt_tokens,
                )
            ]
        raise RuntimeError(
            "Cross-language seek could not be chunked safely because some tags are not "
            "covered by mapping keys. This usually means the translated text mutated a "
            "tag or still depends on unresolved composite mappings."
        )

    chunks: List[_SeekChunk] = []
    offset = 0
    index = 0

    while offset < len(text):
        remaining_text = text[offset:]
        remaining_occurrences = [
            _KeyOccurrence(
                key=item.key,
                start=item.start - offset,
                end=item.end - offset,
            )
            for item in occurrences
            if item.end > offset
        ]

        if not remaining_occurrences:
            chunks.append(
                _SeekChunk(
                    text=remaining_text,
                    index=index,
                    start_char=offset,
                    end_char=len(text),
                    mapping={},
                    needs_model=False,
                    prompt_token_count=0,
                )
            )
            break

        first_occurrence = remaining_occurrences[0]
        if first_occurrence.start > 0:
            passthrough = remaining_text[:first_occurrence.start]
            chunks.append(
                _SeekChunk(
                    text=passthrough,
                    index=index,
                    start_char=offset,
                    end_char=offset + len(passthrough),
                    mapping={},
                    needs_model=False,
                    prompt_token_count=0,
                )
            )
            offset += len(passthrough)
            index += 1
            continue

        chunk = _take_seek_chunk(
            remaining_text,
            mapping,
            remaining_occurrences,
            count_tokens,
            max_chunk_tokens,
            index=index,
            start_char=offset,
        )
        chunks.append(chunk)
        offset += len(chunk.text)
        index += 1

    return chunks


def _candidate_positions(text: str, occurrences: List[_KeyOccurrence], search_end: int) -> List[int]:
    positions = set()

    for pattern in (_SENTENCE_BOUNDARIES, _FALLBACK_BOUNDARIES):
        for match in pattern.finditer(text[:search_end]):
            positions.add(match.start())

    for item in occurrences:
        if 0 < item.start <= search_end:
            positions.add(item.start)
        if 0 < item.end <= search_end:
            positions.add(item.end)

    safe_positions = [
        pos
        for pos in positions
        if 0 < pos < len(text) and _is_safe_split(pos, occurrences)
    ]
    return sorted(safe_positions, reverse=True)


def _take_seek_chunk(
    text: str,
    mapping: Dict[str, List[str]],
    occurrences: List[_KeyOccurrence],
    count_tokens,
    max_tokens: int,
    *,
    index: int,
    start_char: int,
) -> _SeekChunk:
    """Take the next seek chunk without splitting mapping keys across boundaries."""
    if not text:
        raise RuntimeError("Cannot plan an empty seek chunk")

    full_mapping = _local_mapping_for_prefix(mapping, occurrences, len(text))
    full_prompt_tokens = _count_seek_prompt_tokens(count_tokens, text, full_mapping)
    if full_prompt_tokens <= max_tokens:
        return _SeekChunk(
            text=text,
            index=index,
            start_char=start_char,
            end_char=start_char + len(text),
            mapping=full_mapping,
            needs_model=has_tags(text),
            prompt_token_count=full_prompt_tokens,
        )

    chars_per_token = len(text) / max(full_prompt_tokens, 1)
    estimated_chars = max(1, int(max_tokens * chars_per_token))
    search_end = min(estimated_chars + 50, len(text))

    for split_pos in _candidate_positions(text, occurrences, search_end):
        local_mapping = _local_mapping_for_prefix(mapping, occurrences, split_pos)
        chunk_text = text[:split_pos]
        prompt_tokens = _count_seek_prompt_tokens(count_tokens, chunk_text, local_mapping)
        if prompt_tokens <= max_tokens:
            return _SeekChunk(
                text=chunk_text,
                index=index,
                start_char=start_char,
                end_char=start_char + split_pos,
                mapping=local_mapping,
                needs_model=has_tags(chunk_text),
                prompt_token_count=prompt_tokens,
            )

    hard_cut = min(estimated_chars, len(text) - 1)
    while hard_cut > 0 and not _is_safe_split(hard_cut, occurrences):
        hard_cut -= 1

    if hard_cut > 0:
        local_mapping = _local_mapping_for_prefix(mapping, occurrences, hard_cut)
        chunk_text = text[:hard_cut]
        prompt_tokens = _count_seek_prompt_tokens(count_tokens, chunk_text, local_mapping)
        if prompt_tokens <= max_tokens:
            return _SeekChunk(
                text=chunk_text,
                index=index,
                start_char=start_char,
                end_char=start_char + hard_cut,
                mapping=local_mapping,
                needs_model=has_tags(chunk_text),
                prompt_token_count=prompt_tokens,
            )

    first_complete = min((item.end for item in occurrences), default=0)
    if first_complete > 0:
        local_mapping = _local_mapping_for_prefix(mapping, occurrences, first_complete)
        chunk_text = text[:first_complete]
        prompt_tokens = _count_seek_prompt_tokens(count_tokens, chunk_text, local_mapping)
        if prompt_tokens <= max_tokens:
            return _SeekChunk(
                text=chunk_text,
                index=index,
                start_char=start_char,
                end_char=start_char + first_complete,
                mapping=local_mapping,
                needs_model=has_tags(chunk_text),
                prompt_token_count=prompt_tokens,
            )

    raise RuntimeError(
        "A single seek chunk cannot fit in the model budget, even after splitting at "
        "safe key boundaries. Increase --max-chunk-tokens or reduce the mapping size."
    )


def _plan_seek_chunks(
    client: HaSClient,
    text: str,
    mapping: Dict[str, List[str]],
    max_chunk_tokens: int,
) -> List[_SeekChunk]:
    normalized_mapping = _normalize_seek_mapping(client, text, mapping)
    return _plan_seek_chunks_from_mapping(
        text,
        normalized_mapping,
        client.count_tokens,
        max_chunk_tokens,
    )


def _run_model_seek_chunk(
    client: HaSClient,
    text: str,
    mapping: Dict[str, List[str]],
) -> str:
    for attempt in range(2):
        messages = build_seek_messages(mapping, text)
        restored = client.chat(messages)

        if has_tags(restored) and mapping:
            restored = _tool_seek(restored, mapping)

        if _seek_self_check(restored):
            return restored

        if attempt == 0:
            _warn("Model-Seek left unresolved tags; retrying once with the original chunk")

    raise RuntimeError("Model-Seek left unresolved tags after one retry")


def _execute_seek_chunks(
    client: HaSClient,
    chunks: List[_SeekChunk],
    max_parallel_requests: int = DEFAULT_MAX_PARALLEL_REQUESTS,
) -> str:
    outputs = [""] * len(chunks)
    model_chunks = [chunk for chunk in chunks if chunk.needs_model]

    if not model_chunks:
        return "".join(chunk.text for chunk in chunks)

    can_parallelize = isinstance(client, HaSClient) and len(model_chunks) > 1
    max_workers = resolve_parallel_workers(len(model_chunks), max_parallel_requests)

    if can_parallelize and max_workers > 1:
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            futures = [
                (
                    chunk.index,
                    executor.submit(
                        _run_model_seek_chunk,
                        _clone_seek_client(client),
                        chunk.text,
                        chunk.mapping,
                    ),
                )
                for chunk in model_chunks
            ]
            try:
                for index, future in futures:
                    outputs[index] = future.result()
            except BaseException:
                for _, future in futures:
                    future.cancel()
                raise
    else:
        for chunk in model_chunks:
            outputs[chunk.index] = _run_model_seek_chunk(client, chunk.text, chunk.mapping)

    for chunk in chunks:
        if not chunk.needs_model:
            outputs[chunk.index] = chunk.text

    return "".join(outputs)


def estimate_seek_model_request_count(
    text: str,
    mapping: Dict[str, List[str]],
    max_chunk_tokens: int = DEFAULT_MAX_CHUNK_TOKENS,
    *,
    count_tokens: Callable[[str], int],
    original_text: Optional[str] = None,
) -> int:
    """Estimate how many model-backed seek requests a text will need."""
    restored = restore_without_model(text, mapping, original_text=original_text)
    if restored is not None or not has_tags(text):
        return 0

    chunks = _plan_seek_chunks_from_mapping(
        text,
        mapping,
        count_tokens,
        max_chunk_tokens,
    )
    return sum(1 for chunk in chunks if chunk.needs_model)


def estimate_seek_batch_model_request_count(
    documents: List[SeekDocument],
    mapping: Dict[str, List[str]],
    max_chunk_tokens: int = DEFAULT_MAX_CHUNK_TOKENS,
    *,
    count_tokens: Callable[[str], int],
) -> int:
    """Estimate total model-backed seek requests across a batch."""
    return sum(
        estimate_seek_model_request_count(
            document.text,
            mapping,
            max_chunk_tokens=max_chunk_tokens,
            count_tokens=count_tokens,
        )
        for document in documents
    )


def run_seek_batch(
    client: HaSClient,
    documents: List[SeekDocument],
    mapping: Dict[str, List[str]],
    max_chunk_tokens: int = DEFAULT_MAX_CHUNK_TOKENS,
    max_parallel_requests: int = DEFAULT_MAX_PARALLEL_REQUESTS,
) -> Dict[str, Any]:
    """Restore multiple texts with a shared global pool for model-backed chunks."""
    if max_parallel_requests < 1:
        raise ValueError("max_parallel_requests must be >= 1")

    if not documents:
        return {"results": [], "count": 0}

    chunk_plans: List[List[_SeekChunk]] = []
    outputs: List[List[str]] = []
    tasks: List[Tuple[int, _SeekChunk]] = []

    for document_index, document in enumerate(documents):
        chunks = _plan_seek_chunks(client, document.text, mapping, max_chunk_tokens)
        chunk_plans.append(chunks)
        outputs.append([""] * len(chunks))
        for chunk in chunks:
            if chunk.needs_model:
                tasks.append((document_index, chunk))

    can_parallelize = isinstance(client, HaSClient) and len(tasks) > 1
    max_workers = resolve_parallel_workers(len(tasks), max_parallel_requests) if tasks else 0

    if can_parallelize and max_workers > 1:
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            futures = [
                (
                    document_index,
                    chunk.index,
                    executor.submit(
                        _run_model_seek_chunk,
                        _clone_seek_client(client),
                        chunk.text,
                        chunk.mapping,
                    ),
                )
                for document_index, chunk in tasks
            ]
            try:
                for document_index, chunk_index, future in futures:
                    outputs[document_index][chunk_index] = future.result()
            except BaseException:
                for _, _, future in futures:
                    future.cancel()
                raise
    else:
        for document_index, chunk in tasks:
            outputs[document_index][chunk.index] = _run_model_seek_chunk(
                client,
                chunk.text,
                chunk.mapping,
            )

    results: List[Dict[str, Any]] = []
    for document_index, document in enumerate(documents):
        chunks = chunk_plans[document_index]
        for chunk in chunks:
            if not chunk.needs_model:
                outputs[document_index][chunk.index] = chunk.text

        restored_text = "".join(outputs[document_index])
        result: Dict[str, Any] = {"file": document.source, "text": restored_text}
        if len(chunks) > 1:
            result["chunks"] = len(chunks)
        results.append(result)

    return {"results": results, "count": len(results)}


# ======================================================================
# Public entry point
# ======================================================================


def run_seek(
    client: HaSClient,
    text: str,
    mapping: Dict[str, List[str]],
    original_text: Optional[str] = None,
    max_chunk_tokens: int = DEFAULT_MAX_CHUNK_TOKENS,
    max_parallel_requests: int = DEFAULT_MAX_PARALLEL_REQUESTS,
) -> Dict[str, Any]:
    """Restore anonymized text to its original form.

    Implements the Phase 3 workflow:
    1. Check if text contains tags
    2. If same language → Tool-Seek (deterministic) → self-check
    3. If different language or self-check fails → Model-Seek (model-based)

    Language detection is automatic: compares the language of the input text
    against the language of the mapping values (which represent the original
    entities). If they differ (e.g., text was translated), Model-Seek is used.

    Args:
        client: HaSClient connected to llama-server.
        text: Text containing anonymized tags to restore.
        mapping: Mapping dictionary {tag: [original_values]}.
        original_text: Optional original text for language comparison.
                       If not provided, uses mapping values for detection.
        max_chunk_tokens: Maximum tokens per model-backed seek chunk.
        max_parallel_requests: Maximum model-backed seek chunks to run in parallel.

    Returns:
        {"text": "restored original text..."}
    """
    if max_parallel_requests < 1:
        raise ValueError("max_parallel_requests must be >= 1")

    restored = restore_without_model(text, mapping, original_text=original_text)
    if restored is not None:
        return {"text": restored}

    if not has_tags(text):
        return {"text": text}

    if _should_try_tool_seek(text, mapping, original_text=original_text):
        if os.environ.get("HAS_TEXT_VERBOSE") == "1":
            print(
                "Tool-Seek self-check failed, falling back to Model-Seek...",
                file=sys.stderr,
            )

    chunks = _plan_seek_chunks(client, text, mapping, max_chunk_tokens)
    restored_text = _execute_seek_chunks(
        client,
        chunks,
        max_parallel_requests=max_parallel_requests,
    )
    if not _seek_self_check(restored_text):
        raise RuntimeError("Seek output still contains unresolved tags after model retry")
    result = {"text": restored_text}
    if len(chunks) > 1:
        result["chunks"] = len(chunks)
    return result


# ======================================================================
# CLI handler
# ======================================================================


def cmd_restore(args: argparse.Namespace) -> None:
    """Execute the restore command."""
    from ..cli_utils import (
        absolute_path,
        collect_text_documents,
        default_restore_output_dir,
        default_seek_mapping_dir,
        estimate_tokens_for_planning,
        fatal,
        load_mapping_file,
        output,
        read_text,
        required_slots,
        resolve_single_output_path,
        seek_mapping_path,
        write_text_output,
    )
    from ..client import DEFAULT_SERVER
    from ..mapping import has_tags, load_mapping
    from ..server_runtime import acquire_server

    dir_path = getattr(args, "dir", None)

    t0 = time.time()
    if dir_path:
        if args.mapping:
            fatal(
                "invalid_mapping_usage",
                "restore --dir does not support --mapping; use per-file mappings under <dir>/mappings or --mapping-dir.",
            )
        if args.output:
            fatal(
                "invalid_output_usage",
                "restore --dir does not support --output; use --output-dir instead.",
            )

        raw_documents, skipped = collect_text_documents(dir_path)
        documents = [
            SeekDocument(source=item["file"], text=item["text"])
            for item in raw_documents
        ]
        mapping_dir_arg = getattr(args, "mapping_dir", None)
        mapping_dir = Path(mapping_dir_arg) if mapping_dir_arg else default_seek_mapping_dir(dir_path)

        restored_results: List[Optional[Dict[str, Any]]] = [None] * len(documents)
        pending_documents: List[tuple[int, SeekDocument, Dict[str, List[str]]]] = []
        missing_mappings: List[str] = []

        for index, document in enumerate(documents):
            source_path = Path(document.source)
            document_mapping: Optional[Dict[str, List[str]]] = None

            per_file_mapping_path = seek_mapping_path(mapping_dir, source_path)
            if per_file_mapping_path.is_file():
                document_mapping = load_mapping(str(per_file_mapping_path))
            elif has_tags(document.text):
                missing_mappings.append(str(per_file_mapping_path))
                continue

            if document_mapping is None:
                if has_tags(document.text):
                    fatal(
                        "missing_mapping",
                        "Batch restore requires per-file mappings under "
                        f"{mapping_dir} for files that still contain anonymized tags."
                    )

                restored_results[index] = {"file": document.source, "text": document.text}
                continue

            restored = restore_without_model(document.text, document_mapping)
            if restored is not None:
                restored_results[index] = {"file": document.source, "text": restored}
            else:
                pending_documents.append((index, document, document_mapping))

        if missing_mappings:
            fatal(
                "missing_mapping",
                "Missing per-file mapping JSON for batch restore: "
                + ", ".join(sorted(missing_mappings))
            )

        if pending_documents:
            request_count = 0
            for _, document, document_mapping in pending_documents:
                try:
                    request_count += estimate_seek_model_request_count(
                        document.text,
                        document_mapping,
                        max_chunk_tokens=args.max_chunk_tokens,
                        count_tokens=estimate_tokens_for_planning,
                    )
                except RuntimeError:
                    request_count += 1

            with acquire_server(
                DEFAULT_SERVER,
                required_slots=required_slots(
                    max(request_count, 1),
                    args.max_parallel_requests,
                ),
            ) as lease:
                client = lease.create_client()
                for index, document, document_mapping in pending_documents:
                    item = run_seek(
                        client,
                        document.text,
                        document_mapping,
                        max_chunk_tokens=args.max_chunk_tokens,
                        max_parallel_requests=args.max_parallel_requests,
                    )
                    item["file"] = document.source
                    restored_results[index] = item

        output_dir_path = Path(args.output_dir or str(default_restore_output_dir(dir_path)))
        manifest_results: List[Dict[str, Any]] = []
        for item in restored_results:
            if item is None:
                continue
            source_path = Path(item["file"])
            output_path = output_dir_path / source_path.name
            if output_path.resolve() == source_path.resolve():
                fatal("refusing_overwrite", f"Refusing to overwrite source file: {source_path}")
            write_text_output(output_path, str(item["text"]))

            manifest_item: Dict[str, Any] = {
                "file": absolute_path(source_path),
                "output": absolute_path(output_path),
            }
            if "chunks" in item:
                manifest_item["chunks"] = item["chunks"]
            manifest_results.append(manifest_item)

        result = {"results": manifest_results, "count": len(manifest_results)}
        if skipped:
            result["skipped"] = skipped
            result["skipped_count"] = len(skipped)
    else:
        if args.mapping_dir:
            fatal(
                "invalid_output_usage",
                "restore without --dir does not support --mapping-dir.",
            )
        if args.output_dir:
            fatal(
                "invalid_output_usage",
                "restore without --dir does not support --output-dir; use --output instead.",
            )
        if not args.mapping:
            fatal("missing_mapping", "restore requires --mapping in single-file mode.")

        mapping_path = Path(args.mapping)
        mapping = load_mapping_file(args.mapping)
        source_path = Path(args.file) if args.file else None
        output_path = resolve_single_output_path(args.output, input_path=source_path)
        if output_path is not None and output_path.resolve(strict=False) == mapping_path.resolve(strict=False):
            fatal(
                "invalid_output_usage",
                "restore output must be different from the mapping file.",
            )
        text = read_text(args)
        restored = restore_without_model(text, mapping)
        if restored is not None:
            result = {"text": restored}
        else:
            try:
                request_count = estimate_seek_model_request_count(
                    text,
                    mapping,
                    max_chunk_tokens=args.max_chunk_tokens,
                    count_tokens=estimate_tokens_for_planning,
                )
            except RuntimeError:
                request_count = 1

            with acquire_server(
                DEFAULT_SERVER,
                required_slots=required_slots(request_count, args.max_parallel_requests),
            ) as lease:
                client = lease.create_client()
                result = run_seek(
                    client,
                    text,
                    mapping,
                    max_chunk_tokens=args.max_chunk_tokens,
                    max_parallel_requests=args.max_parallel_requests,
                )
        if output_path is not None:
            write_text_output(output_path, str(result["text"]))
            single_result: Dict[str, Any] = {"output": absolute_path(output_path)}
            if "chunks" in result:
                single_result["chunks"] = result["chunks"]
            result = single_result
    elapsed_ms = round((time.time() - t0) * 1000)

    output(
        "restore",
        result,
        timing=args.timing,
        elapsed_ms=elapsed_ms,
    )

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Mapping management: merge, persist, tag utilities."""

from __future__ import annotations

import json
import re
from collections import OrderedDict
from typing import Any, Dict, List, Tuple

# Tag pattern: <类型[编号].分类.属性>
TAG_PATTERN = re.compile(r"<([^<>\[\]]+)\[(\d+)\]\.([^<>\[\].]+)\.([^<>\[\].]+)>")


def find_tags(text: str) -> List[str]:
    """Find all anonymized tags in text.

    Returns:
        List of tag strings, e.g. ["<人名[1].个人.姓名>", "<地址[1].城市.区域>"]
    """
    return [m.group(0) for m in TAG_PATTERN.finditer(text)]


def has_tags(text: str) -> bool:
    """Check if text contains any anonymized tags."""
    return bool(TAG_PATTERN.search(text))


def is_composite_tag(key: str) -> bool:
    """Check if a mapping key contains multiple tags (composite).

    Example composite: "<职务[3].职务.职务名称><人名[1].中文姓名.姓名>"
    """
    matches = TAG_PATTERN.findall(key)
    return len(matches) > 1


def find_composite_entries(
    mapping: Dict[str, List[str]],
) -> Tuple[Dict[str, List[str]], Dict[str, List[str]]]:
    """Separate mapping into atomic and composite entries.

    Returns:
        (atomic_entries, composite_entries)
    """
    atomic = {}
    composite = {}
    for key, values in mapping.items():
        if is_composite_tag(key):
            composite[key] = values
        else:
            atomic[key] = values
    return atomic, composite


def merge_mappings(
    base: Dict[str, List[str]],
    new: Dict[str, List[str]],
) -> Dict[str, List[str]]:
    """Merge new mapping into base, deduplicating values.

    Args:
        base: Existing mapping (will not be mutated).
        new: New mapping entries to merge.

    Returns:
        Merged mapping.
    """
    result = OrderedDict()
    # Copy base
    for key, values in base.items():
        result[key] = list(values)
    # Merge new
    for key, values in new.items():
        if key in result:
            for v in values:
                if v not in result[key]:
                    result[key].append(v)
        else:
            result[key] = list(values)
    return dict(result)


def normalize_mapping_dict(data: Any) -> Dict[str, List[str]]:
    """Validate and normalize a mapping dictionary.

    Accepts either string values or arrays of strings and always returns
    ``Dict[str, List[str]]`` with deduplicated, non-empty values.
    """

    if not isinstance(data, dict):
        raise ValueError("Mapping data must be a JSON object")

    normalized: Dict[str, List[str]] = OrderedDict()

    for raw_key, raw_values in data.items():
        key = str(raw_key).strip()
        if not key:
            raise ValueError("Mapping keys must be non-empty strings")
        if not TAG_PATTERN.search(key):
            raise ValueError(f"Mapping key {key!r} is not a valid anonymized tag")

        if isinstance(raw_values, str):
            values_source = [raw_values]
        elif isinstance(raw_values, list):
            values_source = raw_values
        else:
            raise ValueError(
                f"Mapping entry for {key!r} must be a string or an array of strings"
            )

        values: List[str] = []
        for raw_value in values_source:
            value = str(raw_value).strip()
            if not value:
                raise ValueError(f"Mapping entry for {key!r} contains an empty value")
            if value not in values:
                values.append(value)

        if not values:
            raise ValueError(f"Mapping entry for {key!r} must contain at least one value")

        normalized[key] = values

    return dict(normalized)


def load_mapping(path_or_json: str) -> Dict[str, List[str]]:
    """Load mapping from a JSON file or inline JSON string.

    The input can be:
    - A file path to a JSON file
    - An inline JSON string

    The JSON can be either:
    - A raw mapping dict: {"<tag>": ["value"]}
    - A has_text output: {"text": "...", "mapping": {"<tag>": ["value"]}}
    """
    import os

    # Try as file path first
    if os.path.isfile(path_or_json):
        with open(path_or_json, "r", encoding="utf-8") as f:
            data = json.load(f)
    else:
        # Try as inline JSON string
        try:
            data = json.loads(path_or_json)
        except json.JSONDecodeError:
            raise ValueError(
                f"'{path_or_json}' is neither a valid file path nor a valid JSON string"
            )

    if not isinstance(data, dict):
        raise ValueError("Mapping data must be a JSON object")

    if "mapping" in data:
        if not isinstance(data["mapping"], dict):
            raise ValueError("The 'mapping' field must be a JSON object")
        data = data["mapping"]

    return normalize_mapping_dict(data)


def save_mapping(mapping: Dict[str, List[str]], path: str) -> None:
    """Save mapping to a JSON file with restricted permissions (0600).

    Mapping files are highly sensitive — they can reverse all anonymization.
    """
    import os

    content = json.dumps(mapping, ensure_ascii=False, indent=2)
    # Explicitly tighten permissions after open as well, because the `mode`
    # argument only applies when the file is created and does not fix an
    # existing file that was already too permissive.
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    try:
        if hasattr(os, "fchmod"):
            os.fchmod(fd, 0o600)
        else:
            os.chmod(path, 0o600)
        f = os.fdopen(fd, "w", encoding="utf-8")
    except Exception:
        os.close(fd)
        raise
    with f:
        f.write(content)


def parse_json_tolerant(text: str) -> Any:
    """Tolerantly parse JSON from model output.

    The model output may have minor formatting issues.
    Tries stripping markdown fences and trailing text.
    """
    text = text.strip()

    # Strip markdown code fences
    if text.startswith("```"):
        lines = text.split("\n")
        # Remove first line (```json or ```)
        lines = lines[1:]
        # Remove last line if it's ```
        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]
        text = "\n".join(lines).strip()

    # Try direct parse
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        pass

    # Try to find JSON object or array
    for start_char, end_char in [("{", "}"), ("[", "]")]:
        start = text.find(start_char)
        end = text.rfind(end_char)
        if start != -1 and end > start:
            try:
                return json.loads(text[start : end + 1])
            except json.JSONDecodeError:
                continue

    return None

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Standalone pair mapping helper.

This script contains a self-sufficient implementation of the pair generation
algorithm used by the TagID batch pipeline.  It does not rely on the rest of the
project package and can therefore be executed independently via
``python share/pair_core.py``.
"""

from __future__ import annotations

import argparse
import difflib
import json
import re
import sys
import unicodedata
from collections import OrderedDict
from dataclasses import dataclass
from typing import Any, Dict, Iterable, List, Optional, Sequence, Set, Tuple, Union

# ---------------------------------------------------------------------------
# Token models and constants (mirrors tagid.tag_mapping)
# ---------------------------------------------------------------------------

TAG_PATTERN = re.compile(r"<([^<>\[\]]+)\[(\d+)\]\.([^<>\[\].]+)\.([^<>\[\].]+)>")
CONJ_JUNK_SET: Set[str] = {"及", "和", "与", "到", "的"}


@dataclass(frozen=True)
class TagToken:
    text: str

    def __str__(self) -> str:
        return self.text


@dataclass(frozen=True)
class SpanToken:
    text: str
    kind: str

    def __str__(self) -> str:
        return self.text


Token = Union[str, TagToken, SpanToken]


# ---------------------------------------------------------------------------
# Text normalisation and tokenisation helpers
# ---------------------------------------------------------------------------


def normalize_plain_text(s: str) -> str:
    if s is None:
        return s
    s = s.replace("\r\n", "\n").replace("\r", "\n")
    s = s.replace("\ufeff", "")
    s = s.replace("\u200b", "").replace("\u200c", "").replace("\u200d", "")
    s = unicodedata.normalize("NFC", s)
    return s


def _tokenize_plain_text_with_spans(s: str, *, include_quote_delims: bool = True) -> List[Token]:
    s = normalize_plain_text(s) or ""

    email_re = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,24}")
    url_re = re.compile(r"https?://[^\s\u3000<>\"'）】>)\u4E00-\u9FFF]+", re.IGNORECASE)
    trail_puncts = set(list(".,!?:;)]}")) | set(list("，。！？：；）】】、》”’"))

    tokens: List[Token] = []
    i = 0
    n = len(s)

    def append_span(text: str, kind: str) -> None:
        if text:
            tokens.append(SpanToken(text=text, kind=kind))

    while i < n:
        ch = s[i]

        m = email_re.match(s, i)
        if m:
            span = m.group(0)
            end = m.end()
            while span and span[-1] in trail_puncts:
                end -= 1
                span = span[:-1]
            if span:
                append_span(span, 'email')
                i = end
                continue

        m = url_re.match(s, i)
        if m:
            span = m.group(0)
            end = m.end()
            while span and span[-1] in trail_puncts:
                end -= 1
                span = span[:-1]
            if span:
                append_span(span, 'url')
                i = end
                continue

        if ch == '《':
            j = s.find('》', i + 1)
            if j != -1 and (j - i) <= 200:
                if include_quote_delims:
                    append_span(s[i:j + 1], 'quote')
                else:
                    tokens.append('《')
                    inner = s[i + 1:j]
                    if inner:
                        append_span(inner, 'quote')
                    tokens.append('》')
                i = j + 1
                continue

        tokens.append(ch)
        i += 1

    return tokens


def tokenize_input_text(s: str, *, include_quote_delims: bool = True) -> List[Token]:
    return _tokenize_plain_text_with_spans(s, include_quote_delims=include_quote_delims)


def tokenize_hide_with_tags(hide: str, *, include_quote_delims: bool = True) -> List[Token]:
    tokens: List[Token] = []
    last = 0
    for m in TAG_PATTERN.finditer(hide):
        start, end = m.span()
        if start > last:
            plain = hide[last:start]
            tokens.extend(_tokenize_plain_text_with_spans(plain, include_quote_delims=include_quote_delims))
        tokens.append(TagToken(m.group(0)))
        last = end
    if last < len(hide):
        tail = hide[last:]
        tokens.extend(_tokenize_plain_text_with_spans(tail, include_quote_delims=include_quote_delims))
    return tokens


def render_tokens(tokens: Sequence[Token]) -> str:
    out_parts: List[str] = []
    for t in tokens:
        out_parts.append(str(t))
    return "".join(out_parts)


# ---------------------------------------------------------------------------
# Diff-based entity/tag pairing helpers
# ---------------------------------------------------------------------------


def _is_whitespace_str(t: Token) -> bool:
    return isinstance(t, str) and t.isspace()


def _find_adjacent_composite_group(insert_tokens: Sequence[Token], *, allowed_mid_tokens: Optional[Set[str]] = None) -> Optional[Tuple[int, int]]:
    n = len(insert_tokens)
    allowed_mid_tokens = allowed_mid_tokens or set()
    i = 0
    while i < n and not isinstance(insert_tokens[i], TagToken):
        i += 1
    if i >= n:
        return None
    start = i
    has_tag = False
    while i < n:
        t = insert_tokens[i]
        if isinstance(t, TagToken):
            has_tag = True
            i += 1
            continue
        if _is_whitespace_str(t):
            i += 1
            continue
        if isinstance(t, str) and t in allowed_mid_tokens:
            i += 1
            continue
        break
    end = i
    if not has_tag:
        return None
    return (start, end)


def extract_entity_tag_pairs(
    src_tokens: Sequence[Token],
    dst_tokens: Sequence[Token],
    *,
    isjunk=None,
    allowed_mid_tokens: Optional[Set[str]] = None,
) -> Tuple[List[Tuple[str, str]], Set[str]]:
    opcodes = difflib.SequenceMatcher(isjunk, a=src_tokens, b=dst_tokens, autojunk=False).get_opcodes()
    pairs: List[Tuple[str, str]] = []
    used_mid_tokens: Set[str] = set()

    def render_range(tokens: Sequence[Token], start: int, end: int) -> str:
        return render_tokens(tokens[start:end])

    def lcp(a: str, b: str) -> str:
        n = min(len(a), len(b))
        k = 0
        while k < n and a[k] == b[k]:
            k += 1
        return a[:k]

    def lcsuf(a: str, b: str) -> str:
        na, nb = len(a), len(b)
        k = 0
        while k < na and k < nb and a[na - 1 - k] == b[nb - 1 - k]:
            k += 1
        return a[na - k:] if k > 0 else ""

    def _inside_quote(tokens: Sequence[Token], start_idx: int, end_idx: int) -> bool:
        li = start_idx - 1
        left_q = -1
        while li >= 0:
            t = tokens[li]
            if isinstance(t, str) and t == '《':
                left_q = li
                break
            if isinstance(t, str) and t == '》':
                break
            li -= 1
        if left_q == -1:
            return False
        ri = end_idx
        right_q = -1
        n2 = len(tokens)
        while ri < n2:
            t = tokens[ri]
            if isinstance(t, str) and t == '》':
                right_q = ri
                break
            if isinstance(t, str) and t == '《':
                break
            ri += 1
        return right_q != -1 and left_q < start_idx and end_idx <= right_q

    def _render_skip_tags(tokens: Sequence[Token]) -> str:
        parts: List[str] = []
        for t in tokens:
            if isinstance(t, TagToken):
                continue
            parts.append(str(t))
        return "".join(parts)

    def _first_plain_prefix(tokens: Sequence[Token]) -> str:
        buf: List[str] = []
        i = 0
        n = len(tokens)
        while i < n and isinstance(tokens[i], str) and tokens[i].isspace():
            i += 1
        while i < n:
            t = tokens[i]
            if isinstance(t, TagToken):
                break
            s = str(t)
            if s and not s.isspace():
                buf.append(s)
                i += 1
                continue
            if s.isspace():
                buf.append(s)
                i += 1
                continue
            i += 1
        return "".join(buf)

    def _suffix_overlap_with_right_prefix(a: str, right: str) -> int:
        a = a or ''
        right = right or ''
        max_k = min(len(a), len(right))
        k = max_k
        while k > 0:
            if a.endswith(right[:k]):
                return k
            k -= 1
        return 0

    for idx, (tag, i1, i2, j1, j2) in enumerate(opcodes):
        if tag == "replace":
            del_tokens = src_tokens[i1:i2]
            ins_tokens = dst_tokens[j1:j2]
            grp = _find_adjacent_composite_group(ins_tokens, allowed_mid_tokens=allowed_mid_tokens)
            if grp is None:
                continue
            entity = render_range(del_tokens, 0, len(del_tokens))
            g0, g1 = grp
            comp = render_range(ins_tokens, g0, g1)
            left_ctx = render_range(ins_tokens, 0, g0)
            right_ctx = render_range(ins_tokens, g1, len(ins_tokens))
            pre = lcp(entity, left_ctx)
            suf = lcsuf(entity, right_ctx)
            if pre:
                entity = entity[len(pre):]
            if suf and len(entity) > len(suf):
                entity = entity[:len(entity) - len(suf)]
            try:
                abs_g0 = j1 + g0
                abs_g1 = j1 + g1
                if _inside_quote(dst_tokens, abs_g0, abs_g1):
                    first_plain = _first_plain_prefix(ins_tokens[g1:])
                    if first_plain:
                        pos = entity.rfind(first_plain)
                        if pos != -1:
                            entity = entity[:pos]
                    if entity:
                        right_ctx_plain = _render_skip_tags(ins_tokens[g1:])
                        overlap = _suffix_overlap_with_right_prefix(entity, right_ctx_plain)
                        if overlap and len(entity) > overlap:
                            entity = entity[:-overlap]
            except Exception:
                pass
            entity = entity.strip()
            if not entity:
                entity = render_range(del_tokens, 0, len(del_tokens))
            if allowed_mid_tokens:
                for tt in ins_tokens[g0:g1]:
                    if isinstance(tt, str) and tt in allowed_mid_tokens:
                        used_mid_tokens.add(tt)
            pairs.append((entity, comp))
        elif tag == "insert":
            if idx == 0:
                continue
            prev = opcodes[idx - 1]
            if prev[0] != "delete":
                continue
            del_tokens = src_tokens[prev[1]:prev[2]]
            ins_tokens = dst_tokens[j1:j2]
            grp = _find_adjacent_composite_group(ins_tokens, allowed_mid_tokens=allowed_mid_tokens)
            if grp is None:
                continue
            entity = render_range(del_tokens, 0, len(del_tokens))
            g0, g1 = grp
            comp = render_range(ins_tokens, g0, g1)
            left_ctx = render_range(ins_tokens, 0, g0)
            right_ctx = render_range(ins_tokens, g1, len(ins_tokens))
            pre = lcp(entity, left_ctx)
            suf = lcsuf(entity, right_ctx)
            if pre:
                entity = entity[len(pre):]
            if suf and len(entity) > len(suf):
                entity = entity[:len(entity) - len(suf)]
            try:
                abs_g0 = j1 + g0
                abs_g1 = j1 + g1
                if _inside_quote(dst_tokens, abs_g0, abs_g1):
                    first_plain = _first_plain_prefix(ins_tokens[g1:])
                    if first_plain:
                        pos = entity.rfind(first_plain)
                        if pos != -1:
                            entity = entity[:pos]
                    if entity:
                        right_ctx_plain = _render_skip_tags(ins_tokens[g1:])
                        overlap = _suffix_overlap_with_right_prefix(entity, right_ctx_plain)
                        if overlap and len(entity) > overlap:
                            entity = entity[:-overlap]
            except Exception:
                pass
            entity = entity.strip()
            if not entity:
                entity = render_range(del_tokens, 0, len(del_tokens))
            if allowed_mid_tokens:
                for tt in ins_tokens[g0:g1]:
                    if isinstance(tt, str) and tt in allowed_mid_tokens:
                        used_mid_tokens.add(tt)
            pairs.append((entity, comp))

    return pairs, used_mid_tokens


def compute_mappings_and_self_check_from_tokens(
    src_tokens: Sequence[Token],
    dst_tokens: Sequence[Token],
    hide_s: str,
) -> Tuple["OrderedDict[str, List[str]]", dict, Optional[Any], Optional[Set[str]], Optional[str], Set[str], List[dict]]:
    def _extract_conj_between_tags(tokens: Sequence[Token], conj_set: Set[str]) -> Set[str]:
        selected: Set[str] = set()
        n = len(tokens)
        for idx, t in enumerate(tokens):
            if not (isinstance(t, str) and t in conj_set):
                continue
            li = idx - 1
            while li >= 0 and not isinstance(tokens[li], TagToken):
                li -= 1
            ri = idx + 1
            while ri < n and not isinstance(tokens[ri], TagToken):
                ri += 1
            if li >= 0 and ri < n:
                selected.add(t)
        return selected

    contextual_allowed: Set[str] = _extract_conj_between_tags(dst_tokens, CONJ_JUNK_SET)

    def _mk_isjunk(allowed: Set[str]):
        return (lambda tok: isinstance(tok, str) and tok in allowed) if allowed else None

    strategies: List[Tuple[str, Optional[Any], Optional[Set[str]]]] = [("default", None, None)]
    if contextual_allowed:
        strategies.append(("fallback:contextual-conj", _mk_isjunk(contextual_allowed), contextual_allowed))
        for tok in sorted(list(contextual_allowed)):
            single = {tok}
            strategies.append((f"fallback:contextual-one:{tok}", _mk_isjunk(single), single))

    best_result = None
    best_missing = None

    attempts_summary: List[dict] = []
    default_self_check: Optional[dict] = None
    chosen_isjunk = None
    chosen_allowed = None
    chosen_label = None
    chosen_used_mid_tokens: Set[str] = set()

    for label, sjunk, allowed in strategies:
        pairs, used_mids = extract_entity_tag_pairs(src_tokens, dst_tokens, isjunk=sjunk, allowed_mid_tokens=allowed)
        mappings: "OrderedDict[str, List[str]]" = OrderedDict()
        for entity, tag in pairs:
            arr = mappings.setdefault(tag, [])
            if entity not in arr:
                arr.append(entity)

        hide_tag_set = {m.group(0) for m in TAG_PATTERN.finditer(hide_s)}
        expanded_tags: List[str] = []
        for composite in mappings.keys():
            expanded_tags.extend([m.group(0) for m in TAG_PATTERN.finditer(composite)])
        mapped_tag_set = set(expanded_tags)
        all_values_non_empty = all(len(v) > 0 for v in mappings.values()) if len(mappings) > 0 else True

        set_equal = (hide_tag_set == mapped_tag_set)
        pass_flag = set_equal and all_values_non_empty

        missing_tags = sorted(list(hide_tag_set - mapped_tag_set))
        extra_tags = sorted(list(mapped_tag_set - hide_tag_set))

        self_check: Dict[str, Any] = {
            "pass": pass_flag,
            "summary": {
                "hide_tag_set_count": len(hide_tag_set),
                "mapped_tag_set_count": len(mapped_tag_set),
                "all_values_non_empty": all_values_non_empty,
                "set_equal": set_equal,
            },
            "missing": {
                "count": len(missing_tags),
                "tags": missing_tags[:50],
            },
            "extra": {
                "count": len(extra_tags),
                "tags": extra_tags[:50],
            },
        }

        attempts_summary.append({
            "label": label,
            "pass": pass_flag,
            "missing_count": len(missing_tags),
            "extra_count": len(extra_tags),
        })
        if label == "default":
            default_self_check = self_check

        if pass_flag:
            best_result = (mappings, self_check, sjunk, allowed, label, used_mids)
            chosen_isjunk, chosen_allowed, chosen_label = sjunk, allowed, label
            chosen_used_mid_tokens = used_mids
            break
        miss_count = len(missing_tags)
        if best_missing is None or miss_count < best_missing:
            best_missing = miss_count
            best_result = (mappings, self_check, sjunk, allowed, label, used_mids)
            chosen_isjunk, chosen_allowed, chosen_label = sjunk, allowed, label
            chosen_used_mid_tokens = used_mids

    mappings, self_check, _, _, _, _ = best_result

    if chosen_label is not None:
        used_fallback = (chosen_label != "default")
        strat_obj = {
            "chosen": chosen_label,
            "used_fallback": used_fallback,
            "chosen_isjunk": None if chosen_isjunk is None else "conj_junk",
            "allowed_mid_tokens": None if chosen_allowed is None else sorted(list(chosen_allowed)),
            "used_mid_tokens": sorted(list(chosen_used_mid_tokens)) if chosen_used_mid_tokens else [],
        }
        if used_fallback and default_self_check is not None and not default_self_check.get("pass") and self_check.get("pass"):
            fallback_obj = {
                "used": True,
                "recovered_from": {
                    "missing_count": default_self_check["missing"]["count"],
                    "extra_count": default_self_check["extra"]["count"],
                    "missing_tags_example": default_self_check["missing"]["tags"],
                    "extra_tags_example": default_self_check["extra"]["tags"],
                },
                "recovered_to": {
                    "missing_count": self_check["missing"]["count"],
                    "extra_count": self_check["extra"]["count"],
                },
                "chosen_strategy": chosen_label,
            }
        else:
            fallback_obj = {"used": False}
        self_check["strategy"] = {"chosen": strat_obj["chosen"], "used_fallback": strat_obj["used_fallback"]}

    return mappings, self_check, chosen_isjunk, chosen_allowed, chosen_label, chosen_used_mid_tokens, attempts_summary


# ---------------------------------------------------------------------------
# Public helper mirroring tagid.pair_core
# ---------------------------------------------------------------------------


@dataclass
class PairComputationResult:
    mapping: "OrderedDict[str, List[str]]"
    normalized_mapping: Dict[str, List[str]]
    self_check: Dict[str, Any]
    chosen_strategy: Optional[str]
    used_mid_tokens: Sequence[str]
    attempts_summary: List[Dict[str, Any]]


def _normalize_mapping(raw_mapping: Iterable[Tuple[str, Iterable[Any]]]) -> Dict[str, List[str]]:
    normalized: Dict[str, List[str]] = OrderedDict()
    for key, values in raw_mapping:
        key_str = str(key).strip()
        if not key_str:
            continue
        bucket = normalized.setdefault(key_str, [])
        for value in values:
            val_str = str(value).strip()
            if not val_str or val_str in bucket:
                continue
            bucket.append(val_str)
    return normalized


def compute_pair_mapping(
    input_text: str,
    hide_text: str,
    *,
    include_quote_delims: bool = False,
) -> PairComputationResult:
    src_tokens = tokenize_input_text(str(input_text), include_quote_delims=include_quote_delims)
    dst_tokens = tokenize_hide_with_tags(str(hide_text), include_quote_delims=include_quote_delims)

    (
        mappings,
        self_check,
        _chosen_isjunk,
        _chosen_allowed,
        chosen_label,
        chosen_used_mid_tokens,
        attempts_summary,
    ) = compute_mappings_and_self_check_from_tokens(src_tokens, dst_tokens, str(hide_text))

    normalized_mapping = _normalize_mapping(mappings.items())

    return PairComputationResult(
        mapping=mappings,
        normalized_mapping=normalized_mapping,
        self_check=self_check,
        chosen_strategy=chosen_label,
        used_mid_tokens=sorted(list(chosen_used_mid_tokens)) if chosen_used_mid_tokens else [],
        attempts_summary=attempts_summary,
    )


# ---------------------------------------------------------------------------
# CLI wrapper
# ---------------------------------------------------------------------------


def _read_text(value: Optional[str], file_path: Optional[str], field_name: str) -> str:
    if value is not None and file_path is not None:
        raise SystemExit(f"{field_name}: cannot specify both text and file")
    if value is None and file_path is None:
        raise SystemExit(f"{field_name}: provide content via --{field_name} or --{field_name}-file")
    if file_path is not None:
        with open(file_path, 'r', encoding='utf-8') as f:
            return f.read()
    return value or ''


def main(argv: Optional[List[str]] = None) -> None:
    parser = argparse.ArgumentParser(
        description="Generate pair mapping from original text and anonymized hide text",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog=(
            "Examples:\n"
            "  python pair_core.py --input 'original sentence' --hide '<entity[001].Seg1.Seg2>'\n"
            "  python pair_core.py --input-file input.txt --hide-file hide.txt --dump-self-check\n"
        ),
    )
    parser.add_argument('--input', help='Original input_text content')
    parser.add_argument('--input-file', help='Read original input_text from file')
    parser.add_argument('--hide', help='Hide text content containing tags')
    parser.add_argument('--hide-file', help='Read hide text from file')
    parser.add_argument('--include-quote-delims', action='store_true', help='Include book-title mark delimiters (disabled by default)')
    parser.add_argument('--dump-self-check', action='store_true', help='Dump self-check details to stderr')

    args = parser.parse_args(argv)

    input_text = _read_text(args.input, args.input_file, 'input')
    hide_text = _read_text(args.hide, args.hide_file, 'hide')

    result = compute_pair_mapping(
        input_text=input_text,
        hide_text=hide_text,
        include_quote_delims=args.include_quote_delims,
    )

    json_output = json.dumps(result.normalized_mapping, ensure_ascii=False, separators=(',', ':'))
    print(json_output)

    if args.dump_self_check:
        json.dump(result.self_check, sys.stderr, ensure_ascii=False, indent=2)
        sys.stderr.write('\n')


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Shared concurrency settings for model-backed has_text requests."""

from __future__ import annotations

DEFAULT_MAX_PARALLEL_REQUESTS = 4


def resolve_parallel_workers(total_units: int, max_parallel_requests: int) -> int:
    """Clamp worker count to the configured parallel request budget."""
    if max_parallel_requests < 1:
        raise ValueError("max_parallel_requests must be >= 1")
    return min(total_units, max_parallel_requests)

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""On-demand llama-server management for has_text commands."""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
import os
import re
import shutil
import socket
import subprocess
import sys
import time
from typing import Optional
from urllib.error import URLError
from urllib.parse import urlparse
from urllib.request import urlopen

from .client import DEFAULT_SERVER, HaSClient

DEFAULT_MODEL_PATH = "~/.openclaw/tools/has-anonymizer/models/has_text_model.gguf"
DEFAULT_HEALTH_TIMEOUT_S = 30.0
DEFAULT_CONTEXT_PER_SLOT = 8192
MAX_AUTO_PARALLEL_SLOTS = 4
_LOCAL_HOSTS = {"127.0.0.1", "localhost", "0.0.0.0", "::1", "::"}
_PARALLEL_FLAG_RE = re.compile(r"(?:^|\s)(?:-np|--parallel)(?:=|\s+)(-?\d+)(?=\s|$)")
_CONTEXT_FLAG_RE = re.compile(r"(?:^|\s)(?:-c|--ctx-size)(?:=|\s+)(\d+)(?=\s|$)")


def _verbose_enabled() -> bool:
    return os.environ.get("HAS_TEXT_VERBOSE") == "1"


@dataclass(frozen=True)
class RunningServer:
    """Observed state for a local listener bound to the target port."""

    server_url: str
    port: int
    pid: Optional[int]
    command: Optional[str]
    healthy: bool
    matches_has_model: bool
    parallel_slots: Optional[int]
    context_tokens: Optional[int]


@dataclass
class ServerLease:
    """Lease for a reused or newly started llama-server process."""

    server_url: str
    started_pid: Optional[int] = None
    log_path: Optional[str] = None
    _process: Optional[subprocess.Popen] = field(default=None, repr=False)

    def create_client(self) -> HaSClient:
        return HaSClient(self.server_url)

    def close(self) -> None:
        if self._process is None or self.started_pid is None:
            return

        process = self._process
        if process.poll() is not None:
            return

        process.terminate()
        try:
            process.wait(timeout=10)
        except subprocess.TimeoutExpired:
            process.kill()
            process.wait(timeout=5)

    def __enter__(self) -> ServerLease:
        return self

    def __exit__(self, exc_type, exc, tb) -> None:
        self.close()


def default_model_path() -> str:
    """Return the default local HaS model path."""
    return os.path.expanduser(os.environ.get("HAS_TEXT_MODEL_PATH", DEFAULT_MODEL_PATH))


def parse_parallel_slots(command: str) -> Optional[int]:
    """Extract the configured llama-server slot count from a command line."""
    match = _PARALLEL_FLAG_RE.search(command)
    if not match:
        return None
    return int(match.group(1))


def parse_context_size(command: str) -> Optional[int]:
    """Extract the configured llama-server context size from a command line."""
    match = _CONTEXT_FLAG_RE.search(command)
    if not match:
        return None
    return int(match.group(1))


def _is_loopback_host(host: Optional[str]) -> bool:
    return (host or "").lower() in _LOCAL_HOSTS


def _normalized_local_host(host: Optional[str]) -> str:
    normalized = (host or "").lower()
    if normalized in {"", "localhost", "0.0.0.0", "::1", "::"}:
        return "127.0.0.1"
    return normalized


def _parse_port(server_url: str) -> int:
    parsed = urlparse(server_url)
    if parsed.port is None:
        raise ValueError(f"Server URL must include an explicit port: {server_url}")
    return parsed.port


def _with_port(server_url: str, port: int) -> str:
    parsed = urlparse(server_url)
    host = _normalized_local_host(parsed.hostname)
    scheme = parsed.scheme or "http"
    return f"{scheme}://{host}:{port}"


def _healthcheck(server_url: str) -> bool:
    try:
        with urlopen(f"{server_url.rstrip('/')}/health", timeout=2) as response:
            return response.status == 200
    except URLError:
        return False
    except TimeoutError:
        return False


def _listening_pid(port: int) -> Optional[int]:
    if shutil.which("lsof") is None:
        return None

    result = subprocess.run(
        ["lsof", "-tiTCP:%d" % port, "-sTCP:LISTEN"],
        check=False,
        capture_output=True,
        text=True,
    )
    line = result.stdout.strip().splitlines()
    if not line:
        return None
    try:
        return int(line[0].strip())
    except ValueError:
        return None


def _read_process_command(pid: int) -> Optional[str]:
    result = subprocess.run(
        ["ps", "-p", str(pid), "-o", "command="],
        check=False,
        capture_output=True,
        text=True,
    )
    command = result.stdout.strip()
    return command or None


def inspect_local_server(server_url: str, model_path: Optional[str] = None) -> RunningServer:
    """Inspect the local process currently bound to the target port."""
    resolved_model = os.path.basename(model_path or default_model_path())
    port = _parse_port(server_url)
    pid = _listening_pid(port)
    command = _read_process_command(pid) if pid is not None else None
    healthy = _healthcheck(server_url)
    matches_has_model = bool(
        command
        and "llama-server" in command
        and resolved_model in command
    )
    parallel_slots = parse_parallel_slots(command) if command else None
    context_tokens = parse_context_size(command) if command else None
    return RunningServer(
        server_url=server_url,
        port=port,
        pid=pid,
        command=command,
        healthy=healthy,
        matches_has_model=matches_has_model,
        parallel_slots=parallel_slots,
        context_tokens=context_tokens,
    )


def _target_slots(required_slots: int) -> int:
    """Clamp local auto-managed slot counts to the supported safety ceiling."""
    return min(required_slots, MAX_AUTO_PARALLEL_SLOTS)


def _target_context_tokens(required_slots: int, context_per_slot: int = DEFAULT_CONTEXT_PER_SLOT) -> int:
    """Keep each local auto-managed slot at the requested context budget."""
    return context_per_slot * _target_slots(required_slots)


def _supports_required_slots(observed_slots: Optional[int], required_slots: int) -> bool:
    if observed_slots is None:
        return required_slots <= 1
    if observed_slots < 0:
        return required_slots <= 1
    return observed_slots >= required_slots


def _supports_required_context(
    observed_slots: Optional[int],
    observed_context_tokens: Optional[int],
    context_per_slot: int = DEFAULT_CONTEXT_PER_SLOT,
) -> bool:
    if observed_slots is None or observed_context_tokens is None:
        return False
    if observed_slots <= 0:
        return False
    return observed_context_tokens >= observed_slots * context_per_slot


def _find_free_port(host: str) -> int:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.bind((host, 0))
        sock.listen(1)
        return int(sock.getsockname()[1])


def _port_in_use(host: str, port: int) -> bool:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.settimeout(0.2)
        return sock.connect_ex((host, port)) == 0


def _start_server(
    server_url: str,
    required_slots: int,
    context_tokens: int,
    model_path: str,
) -> ServerLease:
    if shutil.which("llama-server") is None:
        raise RuntimeError("llama-server was not found in PATH")

    model_file = Path(model_path).expanduser()
    if not model_file.is_file():
        raise RuntimeError(
            f"HaS text model not found at {model_file}. "
            "Install has_text_model.gguf before running has-text."
        )

    parsed = urlparse(server_url)
    bind_host = _normalized_local_host(parsed.hostname)
    port = _parse_port(server_url)
    log_path = f"/tmp/llama-server-{port}.log"
    with open(log_path, "ab") as log_handle:
        process = subprocess.Popen(
            [
                "llama-server",
                "--host",
                bind_host,
                "-m",
                str(model_file),
                "-ngl",
                "999",
                "-c",
                str(context_tokens),
                "-np",
                str(required_slots),
                "-fa",
                "on",
                "-ctk",
                "q8_0",
                "-ctv",
                "q8_0",
                "--port",
                str(port),
            ],
            stdout=log_handle,
            stderr=subprocess.STDOUT,
            start_new_session=True,
        )

    deadline = time.time() + DEFAULT_HEALTH_TIMEOUT_S
    while time.time() < deadline:
        if process.poll() is not None:
            raise RuntimeError(
                f"llama-server exited before becoming ready. Check {log_path} for details."
            )
        if _healthcheck(server_url):
            if _verbose_enabled():
                print(
                    f"Started HaS llama-server at {server_url} with {required_slots} slot(s) "
                    f"and context {context_tokens}.",
                    file=sys.stderr,
                )
            return ServerLease(
                server_url=server_url,
                started_pid=process.pid,
                log_path=log_path,
                _process=process,
            )
        time.sleep(0.25)

    process.terminate()
    try:
        process.wait(timeout=5)
    except subprocess.TimeoutExpired:
        process.kill()
        process.wait(timeout=5)

    raise RuntimeError(
        f"Timed out waiting for llama-server at {server_url}. Check {log_path} for details."
    )


def acquire_server(
    server_url: str = DEFAULT_SERVER,
    *,
    required_slots: int = 1,
    model_path: Optional[str] = None,
    context_per_slot: int = DEFAULT_CONTEXT_PER_SLOT,
) -> ServerLease:
    """Reuse or start a local HaS llama-server for the requested workload."""
    if required_slots < 1:
        raise ValueError("required_slots must be >= 1")

    parsed = urlparse(server_url)
    if not _is_loopback_host(parsed.hostname):
        raise RuntimeError(
            f"has-text only supports local loopback servers for on-device privacy. "
            f"Refusing to connect to non-local URL: {server_url}"
        )

    target_slots = _target_slots(required_slots)
    target_context_tokens = _target_context_tokens(required_slots, context_per_slot)
    target_url = _with_port(server_url, _parse_port(server_url))
    observed = inspect_local_server(target_url, model_path=model_path)
    if (
        observed.pid is not None
        and observed.healthy
        and observed.matches_has_model
        and _supports_required_slots(observed.parallel_slots, target_slots)
        and _supports_required_context(observed.parallel_slots, observed.context_tokens, context_per_slot)
    ):
        if _verbose_enabled():
            print(
                f"Reusing HaS llama-server at {target_url}.",
                file=sys.stderr,
            )
        return ServerLease(server_url=target_url)

    start_url = target_url
    bind_host = _normalized_local_host(parsed.hostname)
    if observed.pid is not None or _port_in_use(bind_host, observed.port):
        next_port = _find_free_port(bind_host)
        start_url = _with_port(target_url, next_port)

    return _start_server(
        start_url,
        required_slots=target_slots,
        context_tokens=target_context_tokens,
        model_path=model_path or default_model_path(),
    )

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Tests for lang.py — language detection and same-language comparison."""

from __future__ import annotations

import pytest

from ..lang import detect_script_lang, is_same_language, strip_tags


# ---------------------------------------------------------------------------
# strip_tags
# ---------------------------------------------------------------------------


class TestStripTags:
    def test_removes_tags(self):
        assert strip_tags("<人名[1].个人.姓名>住在北京") == "住在北京"

    def test_no_tags(self):
        assert strip_tags("Hello, world!") == "Hello, world!"

    def test_empty(self):
        assert strip_tags("") == ""

    def test_none(self):
        assert strip_tags(None) == ""


# ---------------------------------------------------------------------------
# detect_script_lang
# ---------------------------------------------------------------------------


class TestDetectScriptLang:
    def test_chinese(self):
        lang, conf = detect_script_lang("这是一段中文文本，用于测试语言检测。")
        assert lang == "zh"
        assert conf > 0.5

    def test_english(self):
        lang, conf = detect_script_lang("This is an English text for testing language detection.")
        assert lang == "en"
        assert conf > 0.5

    def test_japanese(self):
        lang, conf = detect_script_lang("これはテスト用の日本語テキストです。")
        assert lang == "ja"
        assert conf > 0.5

    def test_korean(self):
        lang, conf = detect_script_lang("이것은 한국어 테스트 텍스트입니다.")
        assert lang == "ko"
        assert conf > 0.5

    def test_empty(self):
        lang, conf = detect_script_lang("")
        assert lang is None
        assert conf == 0.0

    def test_tags_stripped_before_detection(self):
        # Only tags, no real text
        lang, conf = detect_script_lang("<人名[1].个人.姓名><地址[1].城市.区域>")
        assert lang is None  # all content is tags

    def test_mixed_with_tags(self):
        lang, conf = detect_script_lang("这是<人名[1].个人.姓名>的测试文本。")
        assert lang == "zh"


# ---------------------------------------------------------------------------
# is_same_language
# ---------------------------------------------------------------------------


class TestIsSameLanguage:
    def test_same_chinese(self):
        assert is_same_language("这是中文", "这也是中文") is True

    def test_same_english(self):
        assert is_same_language("This is English", "This is also English") is True

    def test_different_languages(self):
        assert is_same_language("这是中文文本", "This is English text") is False

    def test_translation_hint_detected(self):
        # Source says "translate to English", output is in English
        source = "请将以下内容翻译为英文：这是一段中文。"
        translated = "This is a paragraph in Chinese."
        assert is_same_language(source, translated) is False

    def test_short_but_detectable_texts(self):
        # Even short text can be detected if script ratio is clear
        # "hi" → 100% Latin → en (0.6 conf), "你" → 100% Han → zh (0.7 conf)
        assert is_same_language("hi", "你") is False

    def test_ambiguous_defaults_to_same(self):
        # Punctuation-only → no script detected → None → defaults to True
        assert is_same_language("...", "!!!") is True

    def test_empty_text_defaults_to_same(self):
        assert is_same_language("", "hello") is True

