        assert is_composite_tag("<人名[1].个人.姓名>") is False

    def test_composite(self):
        assert is_composite_tag("<职务[3].职务.职务名称><人名[1].中文姓名.姓名>") is True

    def test_find_composite_entries(self):
        mapping = {
            "<人名[1].个人.姓名>": ["张三"],
            "<职务[3].职务.职务名称><人名[1].中文姓名.姓名>": ["总经理张三"],
